// Hand-written. Not generated by Speakeasy, and deliberately kept in its own
// file so that persistent edits to generated files stay as small as possible.
//
// Why this exists
// ---------------
// Authlete creates and deletes services through its IdP, which is a different
// host from the regional API cluster. The OpenAPI document declares that host as
// a fixed URL, so Speakeasy resolves it at generation time and bakes it into the
// call. There is no override path: SupportedOptionServerURL is not offered for
// those operations, and per-operation OpenAPI server variables are resolved to
// their default rather than surfaced as configuration.
//
// The practical effect is that only Authlete's shared cloud works. Dedicated
// Cloud and On-Premise deployments run their own IdP and cannot be reached at
// all, so those customers can neither create nor delete a service.
//
// This mirrors the approach taken for the TypeScript SDK in authlete/
// authlete-typescript-sdk#36: intercept at the HTTP layer and match requests by
// URL origin against the generated constant, so the match tracks the spec
// instead of duplicating a hostname.
package provider

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strconv"
	"strings"

	"github.com/authlete/terraform-provider-authlete/internal/sdk/models/operations"
)

// apiServerIDByHost maps an Authlete cluster to the numeric API server ID the
// IdP uses to identify it. The official hand-written SDKs inject this so callers
// never see it; a generated provider has no such table, which is why customers
// would otherwise have to look the number up and type it themselves.
//
// Self-managed and pre-production deployments are not in this map -- they must
// set api_server_id on the provider, or AUTHLETE_API_SERVER_ID in the
// environment. Without one of those, service create and delete fail with an
// apiServerId error.
var apiServerIDByHost = map[string]int64{
	"us.authlete.com": 76281,
	"jp.authlete.com": 53285,
	"eu.authlete.com": 63294,
	"br.authlete.com": 47363,
}

// APIServerIDForServerURL returns the API server ID for a cluster URL, and
// whether one is known. An unrecognised host is not an error: self-managed
// deployments legitimately have an ID that only the operator knows.
func APIServerIDForServerURL(serverURL string) (int64, bool) {
	u, err := url.Parse(serverURL)
	if err != nil {
		return 0, false
	}
	id, ok := apiServerIDByHost[strings.ToLower(u.Hostname())]
	return id, ok
}

// defaultIdpOrigin is the IdP origin the generator baked in, read back from the
// generated operation rather than written out again here. If the spec changes
// the IdP host, this follows it.
func defaultIdpOrigin() string {
	raw := operations.ServiceCreateIdpAPIServerList[operations.ServiceCreateIdpAPIServerIdp]
	// The generated value may contain server-variable placeholders; substituting
	// nothing leaves the literal default, which is what we want to compare.
	u, err := url.Parse(raw)
	if err != nil || u.Host == "" {
		return ""
	}
	return u.Scheme + "://" + u.Host
}

// idpRoutingTransport rewrites requests bound for Authlete's default IdP origin
// so they reach a customer's own IdP instead. Every other request is passed
// through untouched.
type idpRoutingTransport struct {
	// serverURL is the configured cluster, used only to tell a public cluster
	// from a self-managed deployment. See misdirectedIdpError.
	serverURL string
	// idpHost is the replacement IdP host, optionally including a scheme and
	// port. Empty means no rewriting is performed.
	idpHost string
	// apiServerID is injected into IdP request bodies that omit it. Zero means
	// no injection, which is correct for a self-managed deployment whose ID we
	// cannot derive.
	apiServerID int64
	// organizationID is injected the same way. It is a provider attribute rather
	// than a resource one: the IdP needs it to create and delete a service, but
	// the cluster never returns it, so modelling it per-resource makes every
	// imported service look changed and -- because it cannot be updated --
	// propose a destroy. Provider-level also lets one configuration manage
	// several organizations through provider aliases.
	organizationID int64
	next           http.RoundTripper
}

// APIServerIDFromEnv reads the API server id from the environment, used when the
// provider block does not set api_server_id and the cluster is not in the map
// above -- which is the case for Dedicated Cloud, On-Premise and pre-production
// hosts such as nextdev-api.authlete.net.
func APIServerIDFromEnv() int64 {
	v, err := strconv.ParseInt(strings.TrimSpace(os.Getenv("AUTHLETE_API_SERVER_ID")), 10, 64)
	if err != nil {
		return 0
	}
	return v
}

// OrganizationIDFromEnv reads the organization from the environment, used as a
// fallback when the provider block does not set organization_id.
func OrganizationIDFromEnv() int64 {
	v, err := strconv.ParseInt(strings.TrimSpace(os.Getenv("AUTHLETE_ORGANIZATION_ID")), 10, 64)
	if err != nil {
		return 0
	}
	return v
}

// NewIdpRoutingTransport wraps next so that requests to Authlete's default IdP
// origin are redirected to idpHost, and so that IdP request bodies omitting
// apiServerId have apiServerID filled in.
//
// When neither applies the inner transport is returned unchanged, so the
// shared-cloud path keeps exactly its generated behaviour.
func NewIdpRoutingTransport(serverURL, idpHost string, apiServerID, organizationID int64, next http.RoundTripper) http.RoundTripper {
	idpHost = strings.TrimSpace(idpHost)
	if next == nil {
		next = http.DefaultTransport
	}
	// serverURL alone still warrants wrapping: a deployment that is not one of
	// the public clusters must not reach Authlete's shared IdP, even when
	// nothing else is configured. See misdirectedIdpError.
	_, publicCluster := APIServerIDForServerURL(serverURL)
	if idpHost == "" && apiServerID == 0 && organizationID == 0 && publicCluster {
		return next
	}
	return &idpRoutingTransport{
		serverURL:      strings.TrimSpace(serverURL),
		idpHost:        idpHost,
		apiServerID:    apiServerID,
		organizationID: organizationID,
		next:           next,
	}
}

// misdirectedIdpError is returned instead of sending an organization token to
// Authlete's shared IdP from a deployment that is not one of the public
// clusters.
//
// A Dedicated Cloud or On-Premise customer who sets server_url and
// organization_id but forgets idp_host would otherwise have their token sent to
// login.authlete.com, and Authlete answers only that apiServerId must not be
// null -- which says nothing about the host being wrong.
//
// Deliberately narrow: it fires only when the configured server_url is not a
// cluster this provider knows, which is unambiguous. An unrecognised host is
// exactly the deployment that must set idp_host.
func misdirectedIdpError(serverURL, origin string) error {
	// These are terminal messages shown to a practitioner in Terraform output, not
	// Go errors that get wrapped into a longer sentence, so the usual lowercase
	// no-trailing-punctuation convention does not apply.
	//lint:ignore ST1005 user-facing diagnostic
	return fmt.Errorf(
		"refusing to send an Authlete organization token to %s.\n\n"+
			"server_url is %q, which is not one of Authlete's public clusters, so this is a "+
			"Dedicated Cloud or On-Premise deployment with its own identity server. Creating "+
			"and deleting a service goes through that identity server, not the regional "+
			"cluster, and idp_host is not set -- so the request would go to Authlete's shared "+
			"IdP instead of yours.\n\n"+
			"Set idp_host on the provider, or the AUTHLETE_IDP_HOST environment variable, to "+
			"your own identity server.",
		origin, serverURL)
}

// --- clearer failures --------------------------------------------------------

// errNoToken is returned instead of letting every resource fail separately with
// a bare 401. Without a token the SDK sends no Authorization header at all, so
// a configuration with ten resources produced ten identical 401 A001202 errors,
// none of which said that no token was configured.
//
// Checked here rather than in Configure because a token may come from
// AUTHLETE_TOKEN, which a provider config validator cannot see. The transport
// sees what was actually sent.
func errNoToken() error {
	// These are terminal messages shown to a practitioner in Terraform output, not
	// Go errors that get wrapped into a longer sentence, so the usual lowercase
	// no-trailing-punctuation convention does not apply.
	//lint:ignore ST1005 user-facing diagnostic
	return errors.New(
		"no Authlete API token is configured.\n\n" +
			"Set `bearer` on the provider, or the AUTHLETE_TOKEN environment variable.\n\n" +
			"Creating or deleting a service needs an Organization Token. A Service Access " +
			"Token is scoped to one existing service and can read and update it, but cannot " +
			"create another. Both are issued from the Authlete console.")
}

// errWrongTokenType is returned instead of a bare 401 from the IdP. Those two
// endpoints always require an Organization Token, so a 401 there is almost
// always a Service Access Token being used by mistake -- and the raw response
// says only A286301 inside an HTTP dump.
func errWrongTokenType(path string) error {
	// These are terminal messages shown to a practitioner in Terraform output, not
	// Go errors that get wrapped into a longer sentence, so the usual lowercase
	// no-trailing-punctuation convention does not apply.
	//lint:ignore ST1005 user-facing diagnostic
	return fmt.Errorf(
		"Authlete rejected the token for %s (401).\n\n"+
			"Creating and deleting a service goes through Authlete's identity server and "+
			"requires an Organization Token. A Service Access Token is scoped to a single "+
			"existing service and cannot create or delete one, which is the usual cause of "+
			"this.\n\n"+
			"Check that `bearer`, or AUTHLETE_TOKEN, holds an Organization Token from the "+
			"Authlete console.", path)
}

// errIdpUnreachable names the host actually contacted. Go's HTTP client wraps a
// transport error using the original request URL, and the rewrite to a
// customer's own IdP happens inside this transport -- so a connection failure
// reported Post "https://login.authlete.com/api/service" even though that host
// was never contacted, which is actively misleading when debugging one.
func errIdpUnreachable(target *url.URL, err error) error {
	// These are terminal messages shown to a practitioner in Terraform output, not
	// Go errors that get wrapped into a longer sentence, so the usual lowercase
	// no-trailing-punctuation convention does not apply.
	//lint:ignore ST1005 user-facing diagnostic
	return fmt.Errorf("could not reach the identity server at %s://%s: %w\n\n"+
		"This is the host configured as idp_host. The address Terraform reports elsewhere "+
		"may be Authlete's default rather than this one.",
		target.Scheme, target.Host, err)
}

// idpBodyPaths are the IdP operations whose request body carries apiServerId.
var idpBodyPaths = map[string]bool{
	"/api/service":        true,
	"/api/service/remove": true,
}

func (t *idpRoutingTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	// Applies to every request, not only IdP ones: without a token the failure
	// is otherwise one bare 401 per resource.
	if req.Header.Get("Authorization") == "" {
		return nil, errNoToken()
	}

	origin := defaultIdpOrigin()
	if origin == "" || req.URL == nil {
		return t.next.RoundTrip(req)
	}

	if req.URL.Scheme+"://"+req.URL.Host != origin {
		return t.next.RoundTrip(req)
	}

	// Bound for Authlete's shared IdP. If server_url is a deployment this
	// provider does not recognise, that is a self-managed one and the request
	// must not go here.
	if t.idpHost == "" && t.serverURL != "" {
		if _, publicCluster := APIServerIDForServerURL(t.serverURL); !publicCluster {
			return nil, misdirectedIdpError(t.serverURL, origin)
		}
	}

	// RoundTrip must not modify the request it is given.
	cloned := req.Clone(req.Context())

	if t.idpHost != "" {
		target := t.idpHost
		if !strings.Contains(target, "://") {
			target = "https://" + target
		}
		u, err := url.Parse(target)
		if err != nil || u.Host == "" {
			// A malformed override should not silently send IdP traffic to
			// Authlete's shared cloud, so fail loudly rather than passing through.
			return nil, &url.Error{Op: "parse", URL: t.idpHost, Err: err}
		}
		cloned.URL.Scheme = u.Scheme
		cloned.URL.Host = u.Host
		cloned.Host = u.Host
	}

	if idpBodyPaths[req.URL.Path] {
		fields := map[string]int64{}
		if t.apiServerID != 0 {
			fields["apiServerId"] = t.apiServerID
		}
		if t.organizationID != 0 {
			fields["organizationId"] = t.organizationID
		}
		if len(fields) > 0 {
			if err := injectInt64Fields(cloned, fields); err != nil {
				return nil, err
			}
		}
	}

	res, err := t.next.RoundTrip(cloned)
	if err != nil && t.idpHost != "" {
		return nil, errIdpUnreachable(cloned.URL, err)
	}
	if err == nil && res != nil && res.StatusCode == http.StatusUnauthorized && idpBodyPaths[req.URL.Path] {
		if res.Body != nil {
			_, _ = io.Copy(io.Discard, res.Body)
			_ = res.Body.Close()
		}
		return nil, errWrongTokenType(req.URL.Path)
	}
	return res, err
}

// injectInt64Fields fills in JSON body fields that are absent or zero. A value
// the caller set explicitly is never overwritten. A body that is absent or not
// an object is left alone, so a malformed request fails at the API with its own
// error rather than here.
func injectInt64Fields(req *http.Request, fields map[string]int64) error {
	if req.Body == nil {
		return nil
	}

	raw, err := io.ReadAll(req.Body)
	_ = req.Body.Close()
	if err != nil {
		return err
	}

	restore := func(b []byte) {
		req.Body = io.NopCloser(bytes.NewReader(b))
		req.ContentLength = int64(len(b))
		req.GetBody = func() (io.ReadCloser, error) {
			return io.NopCloser(bytes.NewReader(b)), nil
		}
	}

	var body map[string]json.RawMessage
	if err := json.Unmarshal(raw, &body); err != nil {
		restore(raw)
		return nil
	}

	changed := false
	for name, id := range fields {
		if existing, ok := body[name]; ok {
			var n json.Number
			if err := json.Unmarshal(existing, &n); err == nil && n.String() != "0" && n.String() != "" {
				continue
			}
		}
		enc, err := json.Marshal(id)
		if err != nil {
			continue
		}
		body[name] = enc
		changed = true
	}
	if !changed {
		restore(raw)
		return nil
	}

	updated, err := json.Marshal(body)
	if err != nil {
		restore(raw)
		return nil
	}

	restore(updated)
	return nil
}
